#include "GameTestAccess.hpp"
#include <iostream>
static void Check(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
int main(){ChangeWindowMode(TRUE);SetWindowVisibleFlag(FALSE);SetUseDirect3DVersion(DX_DIRECT3D_11);SetGraphMode(640,360,32);if(DxLib_Init()<0)return 2;
auto game = std::make_unique<Game>();
        auto& Config = GameTestAccess::Config(*game);
        auto& Skin = GameTestAccess::Skin(*game);
        try{Skin.Base=new std::remove_pointer_t<decltype(Skin.Base)>();Skin.Info.Resolution={640,360};SetDrawScreen(DX_SCREEN_BACK);Config.RecordPlay=true;Config.RecordFps=30;Config.RecordCodec="libx264";Config.RecordFormat="mp4";Config.SongVolume=100;Config.AutoPlay=true;
std::vector<float> pcm(4*rec::MixRate*2);for(size_t n=0;n<pcm.size()/2;++n)pcm[n*2]=pcm[n*2+1]=(float)(.2*std::sin(n*440.0*6.283185307179586/rec::MixRate));const auto song=fs::absolute("build/record-result-song.wav");Check(rec::WriteWav(song,pcm),"write test audio");
auto render=[&](int frames,bool result){for(int n=0;n<frames;++n){ClearDrawScreen();DrawFillBox(0,0,640,360,result?GetColor(0,0,220):GetColor(220,0,0));game->RecorderCapture();ScreenFlip();std::this_thread::sleep_for(std::chrono::milliseconds(34));}};
auto start=[&](const char* title){game->Chart.OriginalData.Title=title;game->Chart.OriginalData.SongPath=song;game->Chart.OriginalData.SongVolume=100;game->Chart.OriginalData.SeVolume=100;game->Chart.SongSpeed=1;game->Chart.Judge.resize(1);game->NowScene=Game::Scene::Playing;game->RecorderStart();Check(game->Recorder.Active,"recording starts with D3D11 and ffmpeg");game->RecorderNoteSong(0);};
auto join=[&]{if(game->Recorder.Muxer.joinable())game->Recorder.Muxer.join();if(game->Recorder.Finisher.joinable())game->Recorder.Finisher.join();};
start("RecordResultProbe-auto");render(12,false);game->NowScene=Game::Scene::Result;game->PlayingEnd();Check(game->Recorder.Active,"recording continues into Result");const auto cutoff=game->Recorder.SongUntil;Check(cutoff>0.3,"song audio ends at gameplay transition");render(18,true);game->NowScene=Game::Scene::SongSelect;game->ResultEnd();Check(!game->Recorder.Active,"recording ends when leaving Result");join();Check(fs::exists(game->Recorder.OutPath)&&fs::file_size(game->Recorder.OutPath)>0,"result recording exported");std::ofstream("build/record-result-path.txt")<<Game::PathToU8(game->Recorder.OutPath);std::cout<<"PASS: saved result recording, song cutoff="<<cutoff<<", total="<<game->Recorder.Duration<<'\n';
start("RecordResultProbe-discard");render(3,false);game->NowScene=Game::Scene::Result;game->PlayingEnd();render(3,true);game->RecorderFinishResult(false);join();Check(!game->Recorder.Active&&!game->Recorder.AwaitingDecision&&!fs::exists(game->Recorder.OutPath),"discard from Result stops and deletes recording");
start("RecordResultProbe-abort");render(3,false);game->RecorderAbort();game->NowScene=Game::Scene::SongSelect;game->PlayingEnd();join();Check(!game->Recorder.Active&&!fs::exists(game->Recorder.OutPath),"early gameplay exit remains discarded");
Skin.Dispose();DxLib_End();std::cout<<"PASS: Result discard and gameplay abort\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<'\n';if(game->Recorder.Active){game->RecorderAbort();game->RecorderStop();}if(game->Recorder.Muxer.joinable())game->Recorder.Muxer.join();if(game->Recorder.Finisher.joinable())game->Recorder.Finisher.join();Skin.Dispose();DxLib_End();return 1;}}